<?php

/**
 * @file
 * Legacy driver of the differential parity harness (scripts/parity-diff.sh).
 *
 * Enters a scenario through the legacy application over HTTP, with the real
 * handlers and the fields the browser client posts (www/js/app/server/*.js):
 * control/data/add/add_<Class>.php with field_<Class>_<column>, whose
 * control/data/fdms/* hooks set "creador" from the session, and the
 * hand-written events of control/custom/*. Legacy ids are generated by the
 * application (getReplica, crear_id_de_replica); the driver reads the new id
 * of each record from the database (rows before and after the request) only
 * to reference it in later requests, as the browser does from the page.
 *
 * Usage (from scripts/parity-diff.sh; never alone):
 *
 * @code
 * php legacy-driver.php [--characterize] <scenario.json> <base URL> <database> <users.json> <out dir>
 * @endcode
 *
 * With --characterize, only the scenario's characterization steps run
 * (LegacyDriver::characterize()), on the database a previous run filled.
 *
 * users.json maps each scenario user key to {"nick", "password"}; every user
 * but the seeded administrator was created with bin/adduser.php. The
 * administrator gives the others the role "superusuario" over HTTP
 * (add_RolDeUsuario), the only seeded role with a permission ("todos").
 *
 * Writes <out dir>/legacy-users.json (legacy user id => scenario user key)
 * and prints one line per step: "ok", "FAIL" or "VIS" (visibility check).
 * Exit status 0 when every request succeeded.
 */

declare(strict_types=1);

use Ancora\Parity\LegacyDriver;
use Ancora\Parity\Scenario;
use PgSql\Connection;

require __DIR__ . '/src/Scenario.php';
require __DIR__ . '/src/LegacyDriver.php';

$characterize = ($argv[1] ?? '') === '--characterize';
if ($characterize) {
  array_splice($argv, 1, 1);
}
[, $scenario_file, $base, $database, $users_file, $out] = $argv + array_fill(0, 6, NULL);
if ($out === NULL) {
  fwrite(STDERR, "usage: legacy-driver.php <scenario.json> <base URL> <database> <users.json> <out dir>\n");
  exit(2);
}

$db = pg_connect('dbname=' . $database);
if (!$db instanceof Connection) {
  fwrite(STDERR, "cannot connect to $database\n");
  exit(1);
}
$driver = new LegacyDriver(
  Scenario::load($scenario_file),
  $base,
  $db,
  json_decode((string) file_get_contents($users_file), TRUE, 8, JSON_THROW_ON_ERROR),
  $out,
);
if ($characterize) {
  $driver->characterize(json_decode((string) file_get_contents("$out/legacy-users.json"), TRUE, 8, JSON_THROW_ON_ERROR));
}
else {
  $driver->run();
}
exit($driver->failures === 0 ? 0 : 1);
